import boto3

def extract_table_structure(file_path: str) -> list[dict]:
    with open(file_path, 'rb') as file:
        document_bytes = file.read()

    client = boto3.client('textract')
    response = client.analyze_document(
        Document={'Bytes': document_bytes},
        FeatureTypes=['TABLES']
    )

    blocks = response['Blocks']
    block_map = {block['Id']: block for block in blocks}
    table_blocks = [block for block in blocks if block['BlockType'] == 'TABLE']

    tables = []
    for table_block in table_blocks:
        table_id = table_block['Id']
        cells = []

        # Extract child cells of the table
        if 'Relationships' in table_block:
            for relationship in table_block['Relationships']:
                if relationship['Type'] == 'CHILD':
                    for cell_id in relationship['Ids']:
                        cell_block = block_map[cell_id]
                        if cell_block['BlockType'] != 'CELL':
                            continue

                        # Extract text from child words/lines
                        cell_text = []
                        if 'Relationships' in cell_block:
                            for rel in cell_block['Relationships']:
                                if rel['Type'] == 'CHILD':
                                    for child_id in rel['Ids']:
                                        child = block_map[child_id]
                                        if child['BlockType'] in ('WORD', 'SELECTION_ELEMENT'):
                                            cell_text.append(child.get('Text', ''))

                        cells.append({
                            'id': cell_block['Id'],
                            'text': ' '.join(cell_text).strip(),
                            'row_index': cell_block['RowIndex'],
                            'column_index': cell_block['ColumnIndex'],
                            'row_span': cell_block.get('RowSpan', 1),
                            'column_span': cell_block.get('ColumnSpan', 1),
                            'confidence': cell_block['Confidence']
                        })

        # Group cells into rows
        if cells:
            max_row = max(cell['row_index'] for cell in cells)
            rows = [[] for _ in range(max_row)]
            for cell in cells:
                row_idx = cell['row_index'] - 1
                rows[row_idx].append(cell)

            # Sort cells in each row by column index
            for row in rows:
                row.sort(key=lambda c: c['column_index'])

            tables.append({
                'table_id': table_id,
                'cells': cells,
                'rows': [row for row in rows if row]
            })

    return tables
